<template>
  <div id="search">
    <div class="navbar">
      <van-nav-bar title="商品搜索" left-text="返回" left-arrow @click-left="onClickLeft" />
    </div>
    <div class="search">
      <div class="icon">
        <van-icon name="search" size="25px" />
      </div>
      <input placeholder="请输入搜索关键词" maxlength="100" v-model="input"  @keyup.enter="clickSearch(input)" />
      <button @click="clickSearch(input)">搜索</button>
    </div>
    <div class="history">
      <div class="title">
        <span class="indication">最近搜索</span>
        <button class="clear" @click="clearAll"><van-icon name="delete-o" size="14px" />全部清空</button>
      </div>
      <div class="history-list">
        <div class="history-item" v-for="(item) in historyList" :key="item.id" @click="clickSearch(item.name)">
          <!-- 如果长度大于某一个值，就不要完全显示 -->
          <span>{{ item.name }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapMutations, mapState } from 'vuex'

export default {
  name: 'SearchIndex',
  data () {
    return {
      input: ''
    }
  },
  computed: {
    ...mapState('search', ['historyList'])
  },
  methods: {
    ...mapMutations('search', ['appendHistoryList', 'setHistoryList', 'removeHistoryList']),
    onClickLeft () {
      // this.$router.push('/home')
      this.$router.go(-1)
    },
    clickSearch (name) {
      if (name === '') {
        return
      }
      // 存储到vuex、本地
      const item = {
        id: new Date().getTime(),
        name: name
      }
      // console.log(item)
      this.appendHistoryList(item)
      this.input = ''
      // 转发页面
      this.$router.push(`/searchList?name=${name}`)
    },
    clearAll () {
      this.removeHistoryList()
    }
  },
  created () {
    this.setHistoryList()
  }
}
</script>

<style scoped lang="less">
#search {
  .search {
    display: flex;
    flex-direction: row;
    justify-content: center;
    width: 100%;
    margin: 15px 0;

    .icon {
      display: inline-block;
      display: flex;
      background-color: #F7F8FA;
      width: 50px;
      border-top-left-radius: 8px;
      border-bottom-left-radius: 8px;
      align-items: center;

      .van-icon {
        margin: auto;
      }
    }

    input {
      height: 45px;
      width: 220px;
      border: 0;
      background-color: #F7F8FA;
    }

    button {
      height: 45px;
      width: 80px;
      border: 0;
      background-color: #C21401;
      color: white;
      border-top-right-radius: 8px;
      border-bottom-right-radius: 8px;
    }
  }

  .history {

    .title {
      .indication {
        display: inline-block;
        margin: 10px 25px;
        font-size: 20px;
      }

      button {
        display: inline-block;
        border: 0;
        background-color: #dadada;
        padding: 4px;
        margin-left: 140px;
        border-radius: 4px;
        font-size: 14px;
      }
    }

    .history-list {
      display: flex;
      flex-direction: row;
      flex-wrap: wrap;
      margin: 0 16px;

      .title {
        display: inline;

        span {
          font-size: 20px;
        }
      }

      .history-item {
        max-width: 120px;
        min-width: 50px;
        padding: 6px 3px;
        margin: 10px 3px 0 6px;
        border: solid 2px #F2F2F2;
        border-radius: 8px;
        text-align: center;
        font-size: 14px;
        overflow: hidden;

        span {
          white-space: nowrap;
        }
      }
    }
  }

}
</style>
