<template>
  <div id="listBox">

    <div class="navBar">
      <van-nav-bar title="商品列表" left-text="返回" left-arrow @click-left="onClickLeft" />
    </div>

    <div class="search" @click="clickSearch">
      <van-search placeholder="请输入搜索关键词" :value="searchWord" />
    </div>

    <div class="select">
      <button>综合</button>
      <button>销量</button>
      <button>价格</button>
    </div>

    <div class="items">
      <GoodsItem v-for="(item) in searchList" :key="item.goods_id" :item="item"></GoodsItem>
    </div>

  </div>
</template>

<script>
import GoodsItem from '@/components/GoodsItem.vue'
import { search } from '@/api/product'
export default {
  name: 'SearchListPage',
  data () {
    return {
      searchWord: '',
      searchCategoryId: '',
      searchList: []
    }
  },
  methods: {
    onClickLeft () {
      // this.$router.push(`/search?name=${this.searchWord}`)
      this.$router.go(-1)
    },
    clickSearch () {
      this.$router.push('/search')
    }
  },
  components: {
    GoodsItem
  },
  async created () {
    this.searchWord = this.$route.query.name
    this.searchCategoryId = this.$route.query.id
    const response = await search(this.searchCategoryId, this.searchWord)
    // console.log(response)
    this.searchList = response.data.list.data
  }
}
</script>

<style type="text/css" scoped lang="less">
#listBox {

  .select {
    display: flex;
    flex-direction: row;

    button {
      margin: auto;
      padding: 4px;
      border: 0;
      background-color: rgb(255, 255, 255);
    }
  }
}
</style>
